<?php

/* @autogenerated */
declare(strict_types=1);

namespace Tests\integration\Features\Oidc\Stub;

use Civi\Lughauth\Features\Oidc\TokenSecurity\Domain\Gateway\TokenStoreGateway;
use Civi\Lughauth\Features\Oidc\TokenSecurity\Domain\KeyPair;
use Ramsey\Uuid\Uuid;

class InMemoryTokenStore implements TokenStoreGateway
{
    /** @var array<string, list<array{pair: KeyPair, start: \DateTimeImmutable, end: \DateTimeImmutable}>> */
    private array $keys = [];

    public function currentKey(string $tenant): ?KeyPair
    {
        $now = new \DateTimeImmutable();
        foreach (array_reverse($this->keys[$tenant] ?? []) as $entry) {
            if ($entry['start'] <= $now && $now <= $entry['end']) {
                return $entry['pair'];
            }
        }
        return null;
    }

    public function nextKeysExpiration(string $tenant): \DateTimeImmutable
    {
        $latest = new \DateTimeImmutable('@0');
        foreach ($this->keys[$tenant] ?? [] as $entry) {
            if ($entry['end'] > $latest) {
                $latest = $entry['end'];
            }
        }
        return $latest;
    }

    public function listKeys(string $tenant): array
    {
        return array_map(
            static fn (array $entry): KeyPair => $entry['pair'],
            $this->keys[$tenant] ?? []
        );
    }

    public function saveKey(string $tenant, KeyPair $pair, \DateTimeImmutable $start, \DateInterval $caducidad): void
    {
        $this->keys[$tenant][] = [
            'pair' => $pair,
            'start' => $start,
            'end' => $start->add($caducidad),
        ];
    }

    public static function withGeneratedKey(string $tenant): self
    {
        $store = new self();
        $privateKeyResource = openssl_pkey_new([
            'private_key_type' => OPENSSL_KEYTYPE_RSA,
            'private_key_bits' => 2048,
        ]);
        if ($privateKeyResource === false) {
            throw new \RuntimeException('Cannot generate RSA key pair');
        }
        openssl_pkey_export($privateKeyResource, $privateKey);
        $details = openssl_pkey_get_details($privateKeyResource);
        $publicKey = $details !== false ? $details['key'] : '';
        $pair = new KeyPair(
            kid: Uuid::uuid4()->toString(),
            alg: 'RS256',
            keyUse: 'sig',
            privateKey: $privateKey,
            publicKey: $publicKey
        );
        $now = new \DateTimeImmutable();
        $store->saveKey($tenant, $pair, $now->sub(new \DateInterval('PT1H')), new \DateInterval('P7D'));
        return $store;
    }
}
